function numberOfWays(n) {
  const MOD = 1000000007;
  const dp = new Array(n + 1).fill(0);
  dp[0] = 1;

  for (const coin of [1, 2, 6]) {
    for (let sum = coin; sum <= n; sum++) {
      dp[sum] = (dp[sum] + dp[sum - coin]) % MOD;
    }
  }

  let ways = 0;
  for (let fours = 0; fours <= 2 && 4 * fours <= n; fours++) {
    ways = (ways + dp[n - 4 * fours]) % MOD;
  }
  return ways;
}

brute:
function numberOfWays(n) {
  // Choose how many 4s and 6s to use; whatever is left can take any number of 2s from 0 to rest / 2, and 1s fill the rest.
  let total = 0;
  for (let fours = 0; fours <= 2; fours++) {
    for (let sixes = 0; 4 * fours + 6 * sixes <= n; sixes++) {
      const rest = n - 4 * fours - 6 * sixes;
      total += Math.floor(rest / 2) + 1;
    }
  }
  return total % 1000000007;
}

